const CERTIFICATE_DATA = {
  ifct103: "",
  seag16: ""
};

function setCertificateLinks() {
  const links = document.querySelectorAll('[data-certificate]');
  links.forEach((link) => {
    const key = link.dataset.certificate;
    const base64 = CERTIFICATE_DATA[key];
    if (!base64) {
      link.removeAttribute('href');
      link.classList.add('disabled');
      link.textContent = 'Certificado no disponible';
      return;
    }

    link.href = `data:application/pdf;base64,${base64}`;
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', setCertificateLinks);
} else {
  setCertificateLinks();
}
